if __name__ == "__main__":
    os.makedirs("/tmp/browser/slides", exist_ok=True)
    out = []
    for p in POSTS:
        slides = [slide(p["img"], *x, last=(i == 3)) for i, x in enumerate(p["s"])]
        path = f'/tmp/browser/slides/{p["name"]}.json'
        json.dump(slides, open(path, "w", encoding="utf-8"), ensure_ascii=False)
        subprocess.run(["python3", "scripts/render_carousel_slides.py", f'public/social/{p["name"]}', path], check=True)
        out.append({"name": p["name"], "caption": p["caption"]})
    json.dump(out, open("/tmp/browser/slides/batch5.json", "w", encoding="utf-8"), ensure_ascii=False)
